import{_ as r}from"./Voyager2-CLeu7JEM.js";import{_ as o,c as a,h as n,a as t}from"./app-pjenZvZw.js";const l={};function i(c,e){return t(),a("div",null,e[0]||(e[0]=[n('<link rel="stylesheet" href="/css/font-style.css"><img src="'+r+'" style="display:block;margin:0 auto;"><h2 id="preference" tabindex="-1"><a class="header-anchor" href="#preference"><span>Preference</span></a></h2><h3 id="paper" tabindex="-1"><a class="header-anchor" href="#paper"><span>Paper</span></a></h3><p> 3. <a href="https://arxiv.org/abs/2104.09864" target="_blank" rel="noopener noreferrer">RoFormer: Enhanced Transformer with Rotary Position Embedding</a></p><blockquote><ol><li>Transformer位置编码</li></ol></blockquote><p> 4. <a href="https://arxiv.org/abs/1805.02867" target="_blank" rel="noopener noreferrer">Online normalizer calculation for softmax</a></p><blockquote><ol><li>Transformer的Online Softmax</li></ol></blockquote><p> 5. <a href="https://arxiv.org/abs/2303.15647" target="_blank" rel="noopener noreferrer">Scaling Down to Scale Up: A Guide to Parameter-Efficient Fine-Tuning</a></p><blockquote><ol><li>2019年初至2024年中期发表的50余篇微调总结论文</li></ol></blockquote><p> 7. <a href="https://arxiv.org/abs/2111.12800" target="_blank" rel="noopener noreferrer">微型指针</a></p><h3 id="communications-blog" tabindex="-1"><a class="header-anchor" href="#communications-blog"><span>Communications/Blog</span></a></h3><p> 1. <a href="https://0xffff.one/d/1550" target="_blank" rel="noopener noreferrer">如何成为jyy的学生</a></p><p> 2. <a href="https://zhuanlan.zhihu.com/p/46294360" target="_blank" rel="noopener noreferrer">正则表达式引发的血案</a></p><p> 3. <a href="https://cacm.acm.org/news/the-power-of-persona/" target="_blank" rel="noopener noreferrer">人格的力量The Power of Persona</a></p><blockquote><ol><li>随着人工智能代理和模型展现出越来越逼真的个性，一些研究人员呼吁设立防护措施。</li><li>并非所有的人格都是安全的，例如所谓的“黑暗三性格”——自恋、马基雅维利主义和精神病态。</li></ol></blockquote><p> 6. <a href="http://cacm.acm.org/news/speeding-up-hash-tables/" target="_blank" rel="noopener noreferrer">加速哈希表Speeding Up Hash Tables</a></p><blockquote><ol><li>1972 年，斯坦福大学斯坦福·W·阿舍曼工程学教授（荣誉退休）杰弗里·乌尔曼推测，基于贪婪开放寻址哈希表的均匀探测（本质上是使用贪婪算法随机选择一系列槽位，一旦发现有可用槽位，就插入该元素）是最优的。</li><li>Farach-Colton 说：“Iceberg 哈希表具有强大的数学特性，并且在实践中比之前的哈希表速度更快。” 他补充道：“在此基础上，Iceberg 哈希表真正发展出了微型指针。”</li><li>2021年11月，Iceberg哈希算法的作者发表了论文《微型指针》（Tiny Pointers），这篇论文为解决时间和空间问题带来了新的突破。该论文引入了一种新的数据结构对象——微型指针，它可以用来替代传统的指针。</li><li>Farach-Colton解释说：“指针最初只有8位。随着计算机容量的增长，指针也随之增长；先是需要16位，然后是32位和64位。微型指针比传统指针占用更少的内存。”</li><li>后来，Krapivin 发现了一种新的、更优的哈希表结构，它推翻了 Yao 的猜想，但并未推翻 Ullman 的猜想，并且有望比以往的开放寻址哈希表实现更快的搜索速度。这一结果意义重大，但需要注意的是，一些其他类型的哈希表，例如不使用开放寻址的 Iceberg 表，其速度也比 Krapivin 构建的哈希表更快。此外，Tiny Pointers 考虑了数据元素的插入和删除，而 Krapivin 的结构只考虑了插入操作。</li><li>Farach-Colton、Krapivin 和 Kuszmaul 合作，于 2025 年 1 月发表了一篇论文，并于 2025 年 2 月进行了更新，论文标题为“无需重排序的开放寻址的最优界限”。该论文旨在重新审视数据结构中最简单的问题之一：将元素插入开放寻址哈希表，以便以后可以用尽可能少的探测次数检索元素。</li><li>最终：结果表明，使用非贪婪哈希表可以构建一个空间效率和均摊预期查询时间都达到完美的哈希表：兼具两者的优势。第二个结果还获得了比任何贪婪算法都更优的最坏情况预期时间界限。</li><li>康威在评论克拉皮文的研究成果时表示：“虽然这类理论成果可能不会直接催生出最先进的哈希表设计，但它们能够帮助我们从根本上理解哈希表及其相关问题。这可以带来一些间接的应用，例如马赛克页中的微型指针。此外，理论成果还有助于解释哈希表中一些长期存在的未解之谜。”</li></ol></blockquote><p> 8. <a href="https://cacm.acm.org/news/animators-and-special-effects-artists-feel-existential-pinch-of-genai/" target="_blank" rel="noopener noreferrer">动画师和特效艺术家感受到了人工智能带来的生存危机Animators and Special-Effects Artists Feel Existential Pinch of GenAI</a></p><p> 9. <a href="https://cacm.acm.org/opinion/an-anthropologists-guide-to-better-automation/" target="_blank" rel="noopener noreferrer">人类学家的自动化改进指南An Anthropologist’s Guide to Better Automation</a></p><p> 10. <a href="http://cacm.acm.org/blogcacm/program-comprehension-as-a-central-skill-in-cs-education-in-the-era-of-generative-ai/" target="_blank" rel="noopener noreferrer">在生成式人工智能时代，程序理解是计算机科学教育的核心技能Program Comprehension as a Central Skill in CS Education in the Era of Generative AI</a></p><blockquote><ol><li>对于学习者和专业人士而言，核心问题不再是“我能从头开始编写这段代码吗？”，而是“我是否足够理解这段代码，能够对其进行评估、调整和整合？”</li><li>在 GenAI 时代，关键技能不是编写代码，而是阅读、理解、评估和修复代码。因此，当学生要求 AI 工具“用 Python 实现快速排序”时，他们可能在几秒钟内得到正确答案，但他们真的能理解代码的本质吗？</li><li>随着学生越来越依赖人工智能生成代码，如果缺乏扎实的代码理解能力，他们将无法区分人工智能生成的正确代码和存在严重缺陷的代码。计算机科学教育者应该考虑将部分教学重点从代码编写转移到代码理解，并教导学生批判性地分析、调试和验证人工智能生成的解决方案。</li><li>教授程序等价性能够培养学生判断人工智能生成的代码是否正确、安全且符合其需求所需的关键理解能力。</li><li>停机问题（英语：halting problem）是逻辑数学中可计算性理论的一个问题。通俗地说，停机问题就是判断任意一个程序是否能在有限的时间之内结束运行的问题。</li><li>与其将GenAI视为对传统编程教学法的威胁，教育者不如将其视为机遇。3程序理解可以成为连接实践与理论、编码与概念的统一主题。</li><li>对于初学者来说，理解力可以确保他们不会被人工智能生成的代码所淹没，并为他们提供评估和学习的工具。</li><li>对于高级学生来说，理解力将日常编程挑战与等价性和不可判定性等更深层次的理论概念联系起来。</li><li>对于未来的专业人士而言，理解能力有助于培养在协作环境中维护、测试和集成代码所需的技能。</li><li>从这个意义上讲，程序理解能力并非取代编程技能，而是丰富编程技能。它将重点从代码的外观转移到代码的含义。</li></ol></blockquote><p> 11. <a href="https://cacm.acm.org/blogcacm/when-hackers-dont-need-to-hack-you/" target="_blank" rel="noopener noreferrer">当黑客不需要入侵你的时候When Hackers Don’t Need to Hack You</a></p><p> 12. <a href="https://cacm.acm.org/opinion/resilient-infrastructures-via-digital-unification/" target="_blank" rel="noopener noreferrer">通过数字化统一构建弹性基础设施Resilient Infrastructures via Digital Unification</a></p><p> 13. <a href="https://cacm.acm.org/news/learning-how-learning-works/" target="_blank" rel="noopener noreferrer">了解学习是如何运作的Learning How Learning Works</a></p><blockquote><ol><li>信息局部性（相关词语彼此靠近）是语言对人类和机器都易于学习的重要特性。</li><li>对于小众语言，在数据量小的情况下，模型该如何学习</li></ol></blockquote><p> 14. <a href="https://cacm.acm.org/blogcacm/engineering-the-continuum-from-distributed-convergence-to-16-constructs-for-ai-native-network-evolution/" target="_blank" rel="noopener noreferrer">构建连续体：从分布式融合到人工智能原生网络演化的16种结构Engineering the Continuum: From Distributed Convergence to 16 Constructs for AI-Native Network Evolution</a></p><p> 15. <a href="https://cacm.acm.org/blogcacm/challenges-and-pitfalls-in-implementing-okrs-in-software-teams/" target="_blank" rel="noopener noreferrer">软件团队实施 OKR 的挑战与陷阱Challenges and Pitfalls in Implementing OKRs in Software Teams</a></p><blockquote><ol><li>OKR 在纸面上看似简单，实则难以有效实施。</li></ol></blockquote><p> 16. <a href="https://cacm.acm.org/blogcacm/ai-should-make-work-feel-better/" target="_blank" rel="noopener noreferrer">人工智能应该让工作感觉更好AI Should Make Work Feel Better</a></p><p> 17. <a href="https://cacm.acm.org/blogcacm/creationism-and-evolutionism-in-embodied-intelligence/" target="_blank" rel="noopener noreferrer">具身智能中的创造论与进化论Creationism and Evolutionism in Embodied Intelligence</a></p><blockquote><ol><li>试图让单一的机器人形态涵盖所有场景几乎注定会走上一条缓慢而循序渐进的道路。如果要求人形机器人完成清洁、烹饪、照料老人、取物、整理家居等任务，那么每增加一个新领域，就需要开发独立的运动库、数据采集、感知系统、控制逻辑和安全测试。这些都是逐步添加的：每个场景都需要大量的独立工程投入。不同任务之间的技能迁移非常有限，因此不存在“解决X问题就能自动获得Y和Z”的简单方法。</li><li>哪些形态最有可能快速演化？实际上，答案是那些已经大规模出货的机器人。</li><li>这是一个真正的商业飞轮：规模化降低成本，提高可靠性；更高的价值推动更多部署；更多部署产生更多数据，从而进一步提升性能。从演化的角度来看，具身人工智能不太可能从一个孤立设计的理想实体中诞生。它将通过升级和整合那些已经拥有规模、数据和供应链的现有形式而出现。</li><li>在具身智能领域，成本是一种选择压力。能够以可接受的成本提供足够价值的形态才能生存并规模化；而那些针对其主要应用场景过度设计的形态，或许在舞台上光彩夺目，却难以跨越商业鸿沟。</li><li>正确的问题不是“人形机器人：是还是否？”，而是“在生态系统演化之后，在哪些特定场景下，人形机器人最终会成为最佳形态？”答案将在实际部署中显现，而非设计阶段。</li></ol></blockquote><p> 18. <a href="https://cacm.acm.org/blogcacm/writing-good-definitions-comes-down-to-one-basic-rule/" target="_blank" rel="noopener noreferrer">写好的定义归根结底遵循一条基本规则Writing Good Definitions Comes Down to One Basic Rule</a></p><p> 19. <a href="https://cacm.acm.org/opinion/as-answers-get-cheaper-questions-grow-dearer/" target="_blank" rel="noopener noreferrer">答案越便宜，问题越贵。As Answers Get Cheaper, Questions Grow Dearer</a></p><blockquote><ol><li>19世纪30年代和40年代摄影技术的进步开始挑战这一传统观念。起初，摄影似乎对画家构成了威胁。如果机器能够比人手更精确、更快速地记录世界，那么绘画还有什么意义呢？但随着时间的推移，摄影使绘画摆脱了再现现实的束缚。画家们不再需要与相机竞争，去复制现实。相反，他们可以专注于早期相机无法捕捉的微妙之处——光影的变幻、感知的质感以及对熟悉事物的全新诠释。摄影使绘画摆脱了写实主义的束缚，但更有趣的是，取而代之的是什么。</li><li>相机提供了廉价的复制品：大量的答案。印象派画家改变了框架，将艺术定位为提出更深刻问题的基础。</li><li>更重要的是保持好奇心并持续探究的能力。 正因如此，好的问题——即便代价不菲——才具有战略意义。好的问题能够拓展认知领域，重新定义问题。</li></ol></blockquote><p> 20. <a href="https://cacm.acm.org/blogcacm/evolution-of-software-architecture-is-costing-us-more-energy/" target="_blank" rel="noopener noreferrer">软件架构的演进正在消耗我们更多的能源。Evolution of Software Architecture is Costing Us More Energy</a>十分重要的一篇文章</p><blockquote><ol><li>计算机架构演进</li></ol></blockquote><p> 21. <a href="https://cacm.acm.org/news/the-dangers-of-zero-day-exploits/" target="_blank" rel="noopener noreferrer">零日漏洞利用的危险性The Dangers of Zero-Day Exploits</a></p><p> 22. <a href="https://cacm.acm.org/blogcacm/strengthening-safety-boundaries-for-evolving-ai-agents/" target="_blank" rel="noopener noreferrer">加强不断演进的人工智能代理的安全边界Strengthening Safety Boundaries for Evolving AI Agents</a></p><p> 23. <a href="https://cacm.acm.org/opinion/it-takes-a-village-engaging-marginalized-groups-in-computing-survey-research/" target="_blank" rel="noopener noreferrer">众人拾柴火焰高：让边缘群体参与计算机调查研究It Takes A Village: Engaging Marginalized Groups in Computing Survey Research</a></p><p> 24. <a href="https://cacm.acm.org/blogcacm/new-ways-to-corrupt-llms/" target="_blank" rel="noopener noreferrer">腐蚀法学硕士的新方法New Ways to Corrupt LLMs</a></p><blockquote><ol><li>事情从此变得更加奇怪，也更加可怕，出现了一种被称为“归纳后门”的新现象，这是语义泄漏更令人不安的应用</li></ol></blockquote><p> 25. <a href="https://cacm.acm.org/opinion/ai-scraping-and-the-open-web/" target="_blank" rel="noopener noreferrer">人工智能抓取与开放网络AI Scraping and the Open Web</a></p><p> 26. <a href="https://cacm.acm.org/news/virtual-collaboration/" target="_blank" rel="noopener noreferrer">虚拟协作Virtual Collaboration</a></p><p> 27. <a href="https://www.quantamagazine.org/the-year-in-computer-science-20251216/" target="_blank" rel="noopener noreferrer">计算机年鉴The Year in Computer Science</a></p><p> 28. <a href="https://cacm.acm.org/research/sustainable-quantum-computing/" target="_blank" rel="noopener noreferrer">Sustainable Quantum Computing可持续量子计算</a></p><blockquote><ol><li>量子计算生命周期中碳排放基准测试的机遇与挑战。</li></ol></blockquote><p> 29. <a href="https://cacm.acm.org/research-highlights/technical-perspective-toward-a-formally-verified-compiler-for-a-synchronous-functional-data-flow-programming-language/" target="_blank" rel="noopener noreferrer">Technical Perspective: Toward a Formally Verified Compiler for a Synchronous, Functional, Data-Flow Programming Language技术视角：面向同步函数式数据流编程语言的形式化验证编译器</a></p>',48)]))}const m=o(l,[["render",i]]),g=JSON.parse('{"path":"/posts/TechnicalTalk/25-12PaperBlogRead.html","title":"十二月：论文、博客、通讯阅读","lang":"en-US","frontmatter":{"title":"十二月：论文、博客、通讯阅读","description":"十二月：论文、博客、通讯阅读","date":"2025-10-10T00:00:00.000Z","timeline":true,"head":[["meta",{"name":"keywords","content":"十二月：论文、博客、通讯阅读"}],["meta",{"name":"description","content":"十二月：论文、博客、通讯阅读"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["浅读文章"]},"headers":[{"level":2,"title":"Preference","slug":"preference","link":"#preference","children":[{"level":3,"title":"Paper","slug":"paper","link":"#paper","children":[]},{"level":3,"title":"Communications/Blog","slug":"communications-blog","link":"#communications-blog","children":[]}]}],"git":{"updatedTime":1765623247000,"contributors":[{"name":"qwp_p","username":"","email":"qwp20060309@outlook.com","commits":6}],"changelog":[{"hash":"7e703b782536d34fd0a0b0e23898953db577fdcf","time":1765623247000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"Remove model/ from tracking"},{"hash":"aa10a390a6f249561bffad11deb04a3edce6ffa7","time":1765442235000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"Remove model/ from tracking"},{"hash":"b6661dc98d27e0d063d5888791b5461b67378b39","time":1765344716000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"Remove model/ from tracking"},{"hash":"41cf1eccc3cd19cb3ca5088c2452200732ea9e18","time":1765260688000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"Remove model/ from tracking"},{"hash":"2d5f929ef190b2a9f7d15b019aca06381c229af3","time":1765014887000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"Remove model/ from tracking"},{"hash":"7f351ef3adc8b6ccac06b9979306793468463b5e","time":1764913741000,"email":"qwp20060309@outlook.com","author":"qwp_p","message":"Remove model/ from tracking"}]},"filePathRelative":"posts/TechnicalTalk/25-12PaperBlogRead.md","excerpt":"<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<img src=\\"/assets/img/MachineLearning/Voyager2.jpg\\" style=\\"display: block;margin: 0 auto;\\">\\n<h2>Preference</h2>\\n<h3>Paper</h3>\\n<p> 3. <a href=\\"https://arxiv.org/abs/2104.09864\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">RoFormer: Enhanced Transformer with Rotary Position Embedding</a></p>"}');export{m as comp,g as data};
